package dev.omega24.agricrops.command;

import com.mojang.authlib.GameProfile;
import dev.omega24.agricrops.content.*;
import dev.omega24.agricrops.core.content.CropDefinition;
import dev.omega24.agricrops.core.field.*;
import dev.omega24.agricrops.core.genetics.*;
import dev.omega24.agricrops.persistence.*;
import dev.omega24.agricrops.world.*;
import java.util.*;
import net.minecraft.init.*;
import net.minecraft.item.*;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.util.*;
import net.minecraft.util.math.BlockPos;
import net.minecraft.world.WorldServer;
import net.minecraft.world.storage.WorldSavedData;
import net.minecraftforge.common.util.FakePlayer;

/** Deliberate disposable-world qualification. Accelerates normal intervals, never claims natural-time or GUI proof. */
public final class PocAcceptance {
    private PocAcceptance() {}
    private static void check(boolean value, String message) { if (!value) throw new IllegalStateException(message); }
    private static CropTile tile(WorldServer world, BlockPos pos) { return (CropTile) world.getTileEntity(pos); }
    private static void activate(WorldServer world, BlockPos pos, FakePlayer player) {
        player.setPosition(pos.getX() + .5, pos.getY(), pos.getZ() + 1.5);
        player.interactionManager.processRightClickBlock(player, world, player.getHeldItemMainhand(), EnumHand.MAIN_HAND, pos, EnumFacing.UP, .5F, .5F, .5F);
    }
    private static void step(WorldServer world, CropTile tile) { world.getWorldInfo().setWorldTotalTime(world.getTotalWorldTime() + 20); tile.advanceInterval(); }
    private static void growTo(WorldServer world, CropTile tile, long progress) {
        for (int i = 0; i < 2000 && (tile.crop().progress() < progress || tile.crop().rooting() > 0 || (progress == CropDefinitions.get(tile.crop().crop()).timeline().totalTicks() && !tile.crop().funded())); i++) {
            long before = tile.crop().progress(); step(world, tile);
            if (i == 1999) throw new IllegalStateException("Crop stalled: " + tile.getPos() + " at " + before + " " + tile.inspection().getUnformattedText());
        }
    }
    private static void inputs(WorldServer world, BlockPos pos) {
        // Explicit test-fixture inputs, not generated by observation or crop replacement.
        for (int depth = 1; depth <= 3; depth++) {
            String block = world.getBlockState(pos.down(depth)).getBlock().getRegistryName().toString();
            FieldSoils.get(world).put(pos.down(depth), new SoilCell(block, 6500, 9000));
        }
    }
    private static void bed(WorldServer world, BlockPos pos) {
        world.setBlockState(pos.down(), Blocks.FARMLAND.getDefaultState());
        world.setBlockState(pos.down(2), Blocks.DIRT.getDefaultState()); world.setBlockState(pos.down(3), Blocks.CLAY.getDefaultState());
        world.setBlockState(pos, GameContent.CROP_STICKS.getDefaultState()); world.setBlockState(pos.up(2), Blocks.GLOWSTONE.getDefaultState());
    }
    private static void replaceEmpty(WorldServer world, BlockPos pos) { world.setBlockToAir(pos); world.setBlockState(pos, GameContent.CROP_STICKS.getDefaultState()); }
    private static void plant(WorldServer world, BlockPos pos, FakePlayer player, ItemStack seed) {
        player.setHeldItem(EnumHand.MAIN_HAND, seed); activate(world, pos, player);
        check(tile(world, pos).crop() != null && player.getHeldItem(EnumHand.MAIN_HAND).isEmpty(), "Planting failed/seed not debited at " + pos);
    }
    private static ItemStack take(FakePlayer player, Item item) {
        for (int i = 0; i < player.inventory.mainInventory.size(); i++) {
            ItemStack stack = player.inventory.mainInventory.get(i);
            if (stack.getItem() == item) { player.inventory.mainInventory.set(i, ItemStack.EMPTY); return stack; }
        }
        throw new IllegalStateException("Missing output item " + item.getRegistryName());
    }
    private static long window(CropDefinition def, boolean donor) {
        for (long progress = 0; progress <= def.timeline().totalTicks(); progress++) if (def.timeline().phaseAt(progress) == (donor ? def.rules().donor : def.rules().recipient)) return progress;
        throw new IllegalStateException("No authored parent window");
    }
    private static Specimen cross(WorldServer world, BlockPos center, CropTile donor, CropTile recipient, boolean recovery, FakePlayer player) {
        growTo(world, donor, window(CropDefinitions.get(donor.crop().crop()), true));
        growTo(world, recipient, window(CropDefinitions.get(recipient.crop().crop()), false));
        world.getWorldInfo().setWorldTotalTime(world.getTotalWorldTime() + 220);
        replaceEmpty(world, center); CropTile plot = tile(world, center);
        player.setHeldItem(EnumHand.MAIN_HAND, new ItemStack(GameContent.CROP_STICKS)); activate(world, center, player);
        check(plot.crossing() && player.getHeldItemMainhand().isEmpty(), "Actual second-stick interaction did not enable the crossing bed");
        if (recovery) {
            player.setSneaking(true); player.setHeldItem(EnumHand.MAIN_HAND, new ItemStack(Items.DYE, 1, 15));
            try { activate(world, center, player); } finally { player.setSneaking(false); }
            check(plot.backcross() && !player.getHeldItemMainhand().isEmpty(), "Actual sneak-use recovery toggle failed/consumed fertilizer");
        }
        int before = donor.soil().water() + recipient.soil().water(); check(plot.tryBreed(), "Actual adjacent-parent crossing failed");
        check(donor.soil().water() + recipient.soil().water() < before, "Parents did not pay propagation");
        check(plot.crop().origin() == SeedOrigin.BRED && plot.crop().progress() == 0 && plot.crop().plan() == null, "Offspring cloned development/funding");
        return plot.crop().specimen();
    }
    public static void run(WorldServer world, BlockPos base) {
        check(base.getY() > 4 && base.getY() < 250, "Choose Y in 5..249");
        int[] offsets = {0, 2, 4, 7, 8, 9, 12, 14};
        List<BlockPos> targets = new ArrayList<>();
        for (int x : offsets) { for (int y = -3; y <= 2; y++) targets.add(base.add(x, y, 0)); }
        targets.add(base.add(1, 0, 1));
        for (BlockPos pos : targets) check(world.isBlockLoaded(pos) && world.isAirBlock(pos), "POC needs empty loaded fixture positions; nothing replaced: " + pos);
        for (int x : offsets) bed(world, base.east(x));
        FakePlayer player = new FakePlayer(world, new GameProfile(UUID.fromString("bf24f964-39bf-43c4-b04b-08486ee5b3ba"), "[AgriCheck]"));
        net.minecraft.inventory.InventoryCrafting grid = new net.minecraft.inventory.InventoryCrafting(new net.minecraft.inventory.Container() {
            @Override public boolean canInteractWith(net.minecraft.entity.player.EntityPlayer ignored) { return true; }
        }, 3, 3);
        for (int slot : new int[]{0, 2, 3, 4, 5}) grid.setInventorySlotContents(slot, new ItemStack(Items.STICK));
        ItemStack craftedSticks = net.minecraft.item.crafting.CraftingManager.findMatchingResult(grid, world);
        check(craftedSticks.getItem() == Item.getItemFromBlock(GameContent.CROP_STICKS) && craftedSticks.getCount() == 4, "Real crop sticks recipe missing");
        grid.clear(); grid.setInventorySlotContents(0, new ItemStack(Items.WHEAT)); grid.setInventorySlotContents(1, new ItemStack(Items.DYE, 1, 15));
        check(net.minecraft.item.crafting.CraftingManager.findMatchingResult(grid, world).getItem() == GameContent.FOUNDATION, "Crafted foundation recipe missing");
        plant(world, base, player, new ItemStack(Items.WHEAT_SEEDS));
        plant(world, base.east(2), player, new ItemStack(Items.BEETROOT_SEEDS)); plant(world, base.east(4), player, new ItemStack(Items.CARROT));
        plant(world, base.east(7), player, new ItemStack(Items.WHEAT_SEEDS)); plant(world, base.east(9), player, new ItemStack(Items.BEETROOT_SEEDS));
        check(tile(world, base).soil().nutrients() == 0, "Unseen soil minted nutrients");
        player.setHeldItem(EnumHand.MAIN_HAND, new ItemStack(Items.WATER_BUCKET)); activate(world, base, player);
        check(tile(world, base).soil().water() == 1000 && player.getHeldItem(EnumHand.MAIN_HAND).getItem() == Items.BUCKET, "Bucket input not conserved");
        player.setHeldItem(EnumHand.MAIN_HAND, new ItemStack(Items.DYE, 1, 15)); activate(world, base, player);
        check(tile(world, base).soil().nutrients() == 2000 && player.getHeldItem(EnumHand.MAIN_HAND).isEmpty(), "Fertilizer input not conserved");
        player.setHeldItem(EnumHand.MAIN_HAND, new ItemStack(GameContent.COMPOST)); activate(world, base, player);
        check(tile(world, base).soil().organic() == 2000 && player.getHeldItem(EnumHand.MAIN_HAND).isEmpty(), "Compost reserve missing");
        step(world, tile(world, base)); check(tile(world, base).soil().organic() < 2000, "Reserve did not release");
        for (int x : offsets) inputs(world, base.east(x));
        CropTile carrot = tile(world, base.east(4)); growTo(world, carrot, CropDefinitions.get(carrot.crop().crop()).timeline().totalTicks());
        player.setHeldItem(EnumHand.MAIN_HAND, ItemStack.EMPTY); activate(world, base.east(4), player);
        check(take(player, Items.CARROT).getCount() == 2, "Third bundled parent did not produce its native harvest");
        dev.omega24.agricrops.core.environment.Environment observation = WorldEnvironment.sample(world, base);
        check(observation.get("agricrops:height") == base.getY() && observation.get("agricrops:temperature") == world.getBiome(base).getTemperature(base), "World environment lost actual Y/position temperature");
        check(observation.get("agricrops:rain") == (world.isRainingAt(base) ? 1 : 0), "Rain proxy substituted for actual exposure");
        CropTile wheat = tile(world, base); Specimen original = wheat.crop().specimen(); CropDefinition wheatDef = CropDefinitions.get(original.body);
        long vegetative = 0; while (wheatDef.timeline().phaseAt(vegetative) != dev.omega24.agricrops.core.growth.GrowthPhase.VEGETATIVE) vegetative++;
        growTo(world, wheat, vegetative);
        player.setHeldItem(EnumHand.MAIN_HAND, new ItemStack(Items.SHEARS)); activate(world, base, player); ItemStack clipping = take(player, GameContent.CLIPPING);
        check(SpecimenItems.read(clipping).lineage == original.lineage && SpecimenItems.read(clipping).generation == original.generation, "Clipping changed sexual ancestry");
        plant(world, base.east(12), player, clipping); CropTile clone = tile(world, base.east(12));
        check(clone.crop().rooting() == wheatDef.rules().rootingTicks && clone.crop().progress() == 0 && clone.crop().plan() == null, "Clipping skipped rooting/reset");
        step(world, clone); check(clone.crop().rooting() < wheatDef.rules().rootingTicks && clone.crop().progress() == 0, "Rooting did not consume time before growth");
        growTo(world, wheat, window(wheatDef, true));
        FieldSoils.get(world).put(base.down(), new SoilCell("minecraft:farmland", 0, 0)); FieldSoils.get(world).put(base.down(2), new SoilCell("minecraft:dirt", 0, 0));
        int deepBefore = RootZones.read(world, base).cells.get(2).water(); long growthBefore = wheat.crop().progress(); step(world, wheat);
        check(wheat.crop().progress() > growthBefore && RootZones.read(world, base).cells.get(2).water() < deepBefore, "Flowering roots did not debit the real third layer");
        plant(world, base.east(14), player, new ItemStack(GameContent.FOUNDATION)); check(tile(world, base.east(14)).crop().origin() == SeedOrigin.CRAFTED, "Crafted origin missing");
        CropTile seedling = tile(world, base.east(14)); FieldSoils.get(world).put(seedling.getPos().down(), new SoilCell("minecraft:farmland", 0, 0)); step(world, seedling);
        check(seedling.crop().progress() == 0 && seedling.crop().paidWater() == 0, "Germination accessed deep reserves before roots existed");
        if (CropDefinitions.get("poc:tagged_melon") != null) {
            CropDefinition imported = CropDefinitions.get("poc:tagged_melon"); replaceEmpty(world, base.east(14));
            check(!NativeItems.seed(imported, new ItemStack(Items.MELON_SEEDS)), "NBT import accepted an ungated seed");
            ItemStack tagged = new ItemStack(Items.MELON_SEEDS); tagged.setTagCompound(NativeItems.template(imported.rules().seedNbt));
            plant(world, base.east(14), player, tagged); inputs(world, base.east(14)); CropTile custom = tile(world, base.east(14));
            check(WorldEnvironment.sample(world, custom.getPos()).get("poc:greenhouse") == .75, "CT factor provider missing");
            growTo(world, custom, imported.timeline().totalTicks()); player.setHeldItem(EnumHand.MAIN_HAND, ItemStack.EMPTY); activate(world, custom.getPos(), player);
            ItemStack product = take(player, Items.MELON); check(product.hasTagCompound() && product.getTagCompound().getInteger("poc_product") == 1, "Imported product NBT lost");
            check(!Breeding.window(imported, custom.crop().at(200), true), "Import hybrid permission bypassed");
        }
        CropTile donor = tile(world, base.east(7)), recipient = tile(world, base.east(9)); BlockPos center = base.east(8);
        Specimen hybrid = null;
        for (int attempt = 0; attempt < 20; attempt++) {
            hybrid = cross(world, center, donor, recipient, false, player); if (hybrid.products.weights().size() == 2) break;
        }
        check(hybrid.products.weights().size() == 2 && hybrid.traits.loci().containsKey("agricrops:climate"), "Dynamic composition/unlocked trait missing");
        CropTile child = tile(world, center); inputs(world, center); growTo(world, child, CropDefinitions.get(child.crop().crop()).timeline().totalTicks());
        check(!child.getUpdateTag().hasKey("agricrops") && !child.getUpdateTag().hasKey("genome"), "Hidden genotype leaked into crop update packet");
        player.setHeldItem(EnumHand.MAIN_HAND, new ItemStack(GameContent.PROBE)); activate(world, center, player);
        player.inventory.mainInventory.set(10, new ItemStack(Items.PAPER)); player.setHeldItem(EnumHand.MAIN_HAND, new ItemStack(GameContent.ANALYZER)); activate(world, center, player);
        check(player.inventory.mainInventory.get(10).isEmpty() && player.getEntityData().getCompoundTag(net.minecraft.entity.player.EntityPlayer.PERSISTED_NBT_TAG).getCompoundTag("agricrops").getBoolean("trait:agricrops:frost_hardiness"), "Actual analysis did not debit paper/record discovery");
        player.setHeldItem(EnumHand.MAIN_HAND, new ItemStack(GameContent.JOURNAL)); activate(world, center, player);
        NBTTagCompound paid = CropNbt.write(child.crop()); check(CropNbt.write(CropNbt.read(paid)).equals(paid), "Hybrid paid plan failed round trip");
        player.setHeldItem(EnumHand.MAIN_HAND, ItemStack.EMPTY); activate(world, center, player);
        check(child.crop().progress() == CropDefinitions.get(child.crop().crop()).regrowthTicks(), "Numeric regrowth failed");
        check(player.inventory.hasItemStack(new ItemStack(Items.WHEAT)) && player.inventory.hasItemStack(new ItemStack(Items.BEETROOT)), "Actual harvest did not emit both existing parent items");
        check(child.harvestProducts().isEmpty(), "Repeated harvest duplicated outputs");
        net.minecraft.util.NonNullList<ItemStack> drops = net.minecraft.util.NonNullList.create();
        GameContent.CROP_STICKS.getDrops(drops, world, center, world.getBlockState(center), 0);
        ItemStack retained = drops.stream().filter(s -> s.getItem() == GameContent.SPECIMEN).findFirst().get();
        check(CropNbt.seed(SpecimenItems.read(retained)).equals(CropNbt.seed(hybrid)), "Break drop flattened hybrid identity");
        SoilCell depleted = child.soil(); replaceEmpty(world, center); plant(world, center, player, retained); child = tile(world, center);
        check(child.crop().progress() == 0 && child.crop().plan() == null && child.soil().nutrients() == depleted.nutrients(), "Replant copied production or reset soil");
        // Three actual carrier generations, then fixed-line recovery through the same paid world crossing action.
        Specimen lineA = hybrid, lineB = cross(world, center, donor, recipient, false, player);
        for (int generation = 0; generation < 3; generation++) {
            replaceEmpty(world, donor.getPos()); replaceEmpty(world, recipient.getPos());
            plant(world, base.east(7), player, SpecimenItems.of(lineA)); plant(world, base.east(9), player, SpecimenItems.of(lineB));
            donor = tile(world, base.east(7)); recipient = tile(world, base.east(9)); inputs(world, donor.getPos()); inputs(world, recipient.getPos());
            lineA = cross(world, center, donor, recipient, false, player); lineB = cross(world, center, donor, recipient, false, player);
        }
        check(lineA.traits.loci().get("agricrops:climate").fixed, "Three paid stable generations did not fix the locus");
        replaceEmpty(world, donor.getPos()); replaceEmpty(world, recipient.getPos());
        plant(world, base.east(7), player, SpecimenItems.of(lineA)); plant(world, base.east(9), player, new ItemStack(GameContent.FOUNDATION));
        donor = tile(world, base.east(7)); recipient = tile(world, base.east(9)); inputs(world, donor.getPos()); inputs(world, recipient.getPos());
        Specimen reopened = cross(world, center, donor, recipient, true, player); check(!reopened.traits.loci().containsKey("agricrops:climate"), "Fresh backcross did not reopen fixed locus");
        // Keep the original mixed specimen and a partially funded plan for stop/restart qualification.
        replaceEmpty(world, center); plant(world, center, player, SpecimenItems.of(hybrid)); inputs(world, center); child = tile(world, center); step(world, child);
        check(child.crop().paidWater() > 0 && child.crop().plan() != null, "Partial production plan not funded");
        BlockPos reservoirPos = base.add(1, 0, 1); world.setBlockState(reservoirPos, GameContent.RESERVOIR.getDefaultState()); ReservoirTile reservoir = (ReservoirTile) world.getTileEntity(reservoirPos);
        reservoir.addWater(3000); reservoir.addNutrients(4000, false); reservoir.addNutrients(2000, true);
        net.minecraftforge.fluids.capability.IFluidHandler fluid = reservoir.getCapability(net.minecraftforge.fluids.capability.CapabilityFluidHandler.FLUID_HANDLER_CAPABILITY, EnumFacing.UP);
        check(fluid != null && fluid.fill(new net.minecraftforge.fluids.FluidStack(net.minecraftforge.fluids.FluidRegistry.LAVA, 1000), true) == 0, "Reservoir accepted a fictitious non-water source");
        check(fluid.drain(100, true).amount == 100 && reservoir.water() == 2900 && fluid.fill(new net.minecraftforge.fluids.FluidStack(net.minecraftforge.fluids.FluidRegistry.WATER, 100), true) == 100, "Forge pipe capability does not use the same finite tank");
        FieldSoils.get(world).put(base.down(), new SoilCell("minecraft:farmland", 0, 0)); reservoir.advanceInterval();
        check(reservoir.water() < 3000 && wheat.soil().water() > 0, "Controller did not debit its finite tank into actual soil");
        ReservoirTile restored = new ReservoirTile(); restored.readFromNBT(reservoir.writeToNBT(new NBTTagCompound())); check(restored.water() == reservoir.water() && restored.organic() == reservoir.organic(), "Controller state round trip failed");
        NBTTagCompound future = reservoir.writeToNBT(new NBTTagCompound()); future.setInteger("agriSchema", 99); ReservoirTile rejected = new ReservoirTile(); rejected.readFromNBT(future);
        check(rejected.quarantined() && rejected.writeToNBT(new NBTTagCompound()).equals(future) && rejected.getCapability(net.minecraftforge.fluids.capability.CapabilityFluidHandler.FLUID_HANDLER_CAPABILITY, EnumFacing.UP) == null, "Rejected reservoir data was reset/exposed");
        BlockPos customBed = base.east(14); world.setBlockState(customBed.down(), Blocks.SAND.getDefaultState());
        SoilProfile sand = PocContent.soils().get("minecraft:sand"); FieldSoils.get(world).put(customBed.down(), new SoilCell(sand.block, sand.waterCapacity, sand.nutrientCapacity));
        player.setHeldItem(EnumHand.MAIN_HAND, new ItemStack(Items.WATER_BUCKET)); activate(world, customBed, player);
        check(player.getHeldItem(EnumHand.MAIN_HAND).getItem() == Items.WATER_BUCKET, "Full custom-capacity soil consumed a water bucket");
        player.setHeldItem(EnumHand.MAIN_HAND, new ItemStack(Items.DYE, 1, 15)); activate(world, customBed, player);
        check(!player.getHeldItem(EnumHand.MAIN_HAND).isEmpty(), "Full custom-capacity soil consumed fertilizer");
        NBTTagCompound evidence = new NBTTagCompound(); evidence.setLong("base", base.toLong()); evidence.setTag("seed", CropNbt.seed(hybrid)); evidence.setInteger("planWater", child.crop().plan().water); evidence.setInteger("paidWater", child.crop().paidWater()); evidence.setInteger("reservoirWater", reservoir.water());
        Evidence record = new Evidence(); record.data = evidence; record.markDirty(); world.getPerWorldStorage().setData(Evidence.NAME, record);
    }
    public static void saved(WorldServer world, BlockPos base) {
        Evidence record = (Evidence) world.getPerWorldStorage().getOrLoadData(Evidence.class, Evidence.NAME);
        check(record != null && record.data.getLong("base") == base.toLong(), "No matching persisted POC evidence");
        CropTile child = tile(world, base.east(8));
        check(CropNbt.seed(child.crop().specimen()).equals(record.data.getCompoundTag("seed")), "Saved hybrid identity/composition/traits/ancestry changed");
        check(child.crop().plan() != null && child.crop().plan().water == record.data.getInteger("planWater") && child.crop().paidWater() >= record.data.getInteger("paidWater"), "Saved production funding/price changed");
        ReservoirTile reservoir = (ReservoirTile) world.getTileEntity(base.add(1, 0, 1)); check(reservoir.water() <= record.data.getInteger("reservoirWater"), "Reload minted reservoir water");
    }
    public static final class Evidence extends WorldSavedData {
        static final String NAME = "agricrops_poc_evidence"; NBTTagCompound data = new NBTTagCompound();
        public Evidence() { super(NAME); } public Evidence(String name) { super(name); }
        @Override public void readFromNBT(NBTTagCompound tag) { data = tag.copy(); }
        @Override public NBTTagCompound writeToNBT(NBTTagCompound tag) { tag.merge(data); return tag; }
    }
}
